config.css:
/* ════════ DARK MODE ════════ */
[data-theme="dark"] {
  color-scheme: dark;

  /* core palette dark */
  --mp-bg-base: #180c0e;
  --mp-bg-surface: rgba(24, 10, 14, 0.97);
  --mp-bg-elevated: rgba(30, 14, 18, 0.97);
  --mp-bg-inset: rgba(40, 18, 24, 0.97);
  --mp-chat-bg: #180c0e;
  --mp-chat-tint: rgba(24, 10, 14, 0.95);
  --mp-user-tint: rgba(24, 10, 14, 0.98);
  --mp-bot-tint: rgba(30, 14, 18, 0.98);

  --mp-text-primary: rgba(240, 192, 204, 1);
  --mp-text-secondary: rgba(200, 110, 130, 1);
  --mp-text-muted: rgba(160, 96, 120, 0.7);
  --mp-text-italics: rgba(200, 110, 130, 1);
  --mp-text-quote: rgba(150, 70, 90, 1);
  --mp-text-underline: rgba(170, 85, 105, 1);
  --mp-text-inverted: #180c0e;

  --mp-pink: #c06878;
  --mp-pink-soft: rgba(192, 104, 120, 0.35);
  --mp-purple: #963a4b;
  --mp-purple-soft: rgba(150, 58, 75, 0.2);
  --mp-blue: #8c3c50;
  --mp-blue-soft: rgba(140, 60, 80, 0.2);
  --mp-mint: #6e4a52;
  --mp-border: rgba(140, 60, 80, 0.8);
  --mp-shadow: rgba(0, 0, 0, 0.7);

  --mp-rainbow: linear-gradient(90deg, #c06878, #963a4b, #8c3c50);
  --mp-rainbow-vertical: linear-gradient(180deg, #c06878, #963a4b, #8c3c50);

  --background: var(--mp-bg-base);
  --marinara-app-background-paint: var(--mp-bg-base);
  --foreground: var(--mp-text-primary);

  --card: var(--mp-bg-surface);
  --card-foreground: var(--mp-text-primary);
  --popover: var(--mp-bg-elevated);
  --popover-foreground: var(--mp-text-primary);

  --primary: var(--mp-purple);
  --primary-foreground: var(--mp-text-inverted);

  --secondary: var(--mp-bg-elevated);
  --secondary-foreground: var(--mp-text-primary);

  --muted: var(--mp-bg-inset);
  --muted-foreground: var(--mp-text-muted);

  --accent: var(--mp-purple-soft);
  --accent-foreground: var(--mp-text-primary);

  --destructive: #e54666;
  --destructive-foreground: var(--mp-text-inverted);

  --border: var(--mp-border);
  --input: var(--mp-border);
  --ring: var(--mp-purple);
  --radius: 1rem;

  --sidebar: var(--mp-bg-elevated);
  --sidebar-foreground: var(--mp-text-primary);
  --sidebar-border: var(--mp-border);
  --sidebar-accent: var(--mp-purple-soft);
  --sidebar-accent-foreground: var(--mp-text-primary);

  --glow-primary: rgba(192, 104, 120, 0.3);
  --glow-accent: rgba(150, 58, 75, 0.3);

  --marinara-app-accent-solid: var(--mp-purple);
  --marinara-app-accent-gradient: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95));
  --marinara-chat-chrome-accent: var(--mp-purple);
  --marinara-chat-chrome-accent-gradient: var(--marinara-app-accent-gradient);
  --marinara-chat-chrome-text: var(--mp-text-primary);
  --marinara-chat-chrome-panel-muted: rgba(200, 146, 159, 0.6);

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-xl: 24px;

  /* rest of the silly rules */
  body,
  .app-shell,
  #root,
  #main,
  .main-container,
  .app-background,
  .chat-container,
  .chat-background,
  .message-list,
  .chat-messages,
  .chat-view,
  .conversation-pane,
  .mari-chat-shell,
  .mari-chat-background {
    background-color: var(--background) !important;
    color: var(--foreground) !important;
  }

  ::selection {
    background: rgba(192, 104, 120, 1) !important;
    color: #180c0e !important;
  }

  .glass,
  .glass-strong,
  .card,
  .panel,
  .sidebar,
  .drawer,
  .modal-content,
  .settings-section,
  .chat-list,
  .character-card,
  .persona-card {
    background-color: var(--card) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-md) !important;
  }

  .card:hover,
  .character-card:hover,
  .persona-card:hover {
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 12px var(--glow-primary) !important;
  }

  .menu,
  .dropdown,
  .popover,
  .tooltip,
  .toast {
    background-color: var(--popover) !important;
    border: 1px solid var(--mp-border) !important;
    box-shadow: 0 0 14px var(--glow-primary) !important;
  }

  .tag,
  .badge {
    background-color: var(--mp-purple-soft) !important;
    color: var(--mp-text-secondary) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: 999px !important;
    padding: 2px 8px !important;
  }

  hr,
  .divider {
    border-color: var(--mp-border) !important;
  }

  code,
  pre,
  .code-block,
  .mari-message-content .mari-md-inline-code,
  .mari-message-content .mari-md-codeblock {
    background-color: var(--mp-bg-inset) !important;
    color: var(--mp-text-secondary) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-sm) !important;
  }

  h2.mari-chrome-text-strong {
    background: var(--mp-rainbow) !important;
    background-size: 200% auto !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
    color: transparent !important;
    font-weight: 700 !important;
  }

  input,
  textarea,
  select,
  .search-input {
    background-color: var(--mp-bg-elevated) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-sm) !important;
    color: var(--mp-text-primary) !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    outline: none !important;
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 0 3px rgba(150, 58, 75, 0.2) !important;
  }

  button,
  .btn,
  .action-button {
    background-color: var(--mp-bg-elevated) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-sm) !important;
    color: var(--mp-text-primary) !important;
    transition: all 0.3s ease !important;
  }

  button:hover,
  .btn:hover,
  .action-button:hover {
    border-color: var(--mp-purple) !important;
    color: var(--mp-text-secondary) !important;
    box-shadow: 0 0 10px rgba(150, 58, 75, 0.25) !important;
  }

  button.primary,
  .btn-primary,
  .send-button {
    background: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: var(--mp-text-inverted) !important;
    border: none !important;
  }

  button.primary:hover,
  .btn-primary:hover,
  .send-button:hover {
    background: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 14px var(--glow-accent) !important;
  }

  a,
  .link {
    color: var(--mp-text-secondary) !important;
    text-decoration: none !important;
  }

  a:hover,
  .link:hover {
    color: var(--mp-text-underline) !important;
  }

  #top-bar,
  .top-bar,
  .mari-top-bar {
    height: var(--topBarBlockSize, 48px) !important;
    box-shadow: none !important;
    background: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    margin-top: 0px !important;
    margin-bottom: 0px !important;
    border-bottom: 1px solid var(--mp-border) !important;
  }

  .mari-topbar-action {
    background: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    border: 1px solid rgba(140, 60, 80, 0.6) !important;
    border-radius: 50% !important;
    box-shadow: 0 0.25rem 0.75rem rgba(192, 104, 120, 0.18) !important;
    transition: all 0.3s ease !important;
  }

  .mari-topbar-action svg,
  .mari-topbar-action .mari-icon,
  .mari-topbar-action i {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
    stroke-width: 1.5px !important;
  }

  .mari-topbar-action:hover {
    background: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    border-color: rgba(192, 104, 120, 0.9) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.4) !important;
  }

  .mari-topbar-action:hover svg,
  .mari-topbar-action:hover .mari-icon,
  .mari-topbar-action:hover i {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
    stroke-width: 1.5px !important;
  }

  .mari-topbar-action:active {
    transform: scale(0.98) !important;
  }

  .mari-topbar-action[aria-current="page"],
  .mari-topbar-action[aria-selected="true"],
  .mari-topbar-action[data-active="true"],
  .mari-topbar-action.active {
    box-shadow: 0 0 0 2px rgba(192, 104, 120, 0.5), 0 0.35rem 0.9rem rgba(192, 104, 120, 0.3) !important;
    filter: brightness(1.08) !important;
  }

  .nav-item.active,
  .sidebar-item.active,
  .tab-active {
    background: rgba(150, 58, 75, 0.15) !important;
    border-left: 3px solid var(--mp-purple) !important;
    color: var(--mp-text-secondary) !important;
  }

  .nav-item:hover,
  .sidebar-item:hover {
    background: rgba(150, 58, 75, 0.08) !important;
  }

  .mari-sidebar-header > div > div:first-child {
    background: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    border: 1px solid rgba(140, 60, 80, 0.6) !important;
    box-shadow: 0 0.25rem 0.75rem rgba(192, 104, 120, 0.18) !important;
    transition: all 0.3s ease !important;
  }

  .mari-sidebar-header > div > div:first-child svg {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
    stroke-width: 1.5px !important;
  }

  .mari-sidebar-header > div > div:first-child:hover {
    background: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    border-color: rgba(192, 104, 120, 0.9) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.4) !important;
  }

  .mari-sidebar-header > div > div:first-child:hover svg {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-amber-400.to-orange-500 {
    box-shadow: none !important;
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  .from-amber-400.to-orange-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-amber-400.to-orange-500 svg,
  .from-amber-400.to-orange-500 i,
  .from-amber-400.to-orange-500 .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  [class*="bg-[linear-gradient(135deg,#4de5dd_0%,#eb8951_52%,#e15c8c_100%)]"] {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: none !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  [class*="bg-[linear-gradient(135deg,#4de5dd_0%,#eb8951_52%,#e15c8c_100%)]"]:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  [class*="bg-[linear-gradient(135deg,#4de5dd_0%,#eb8951_52%,#e15c8c_100%)]"] svg,
  [class*="bg-[linear-gradient(135deg,#4de5dd_0%,#eb8951_52%,#e15c8c_100%)]"] i,
  [class*="bg-[linear-gradient(135deg,#4de5dd_0%,#eb8951_52%,#e15c8c_100%)]"] .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-amber-400.to-orange-500[class*="focus:ring-[var(--marinara-chat-chrome-focus-ring)]"] {
    border-radius: 9999px !important;
  }

  [class*="bg-black/45"][class*="opacity-0"][class*="group-hover:opacity-100"] {
    border-radius: 9999px !important;
  }

  .from-sky-400.to-blue-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: var(--mp-text-primary) !important;
    transition: background-image 0.3s ease, box-shadow 0.3s ease !important;
  }

  .from-sky-400.to-blue-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.3) !important;
  }

  .from-sky-400.to-indigo-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  .from-sky-400.to-indigo-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-sky-400.to-indigo-500 svg,
  .from-sky-400.to-indigo-500 i,
  .from-sky-400.to-indigo-500 .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-rose-400.to-pink-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  .from-rose-400.to-pink-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-rose-400.to-pink-500 svg,
  .from-rose-400.to-pink-500 i,
  .from-rose-400.to-pink-500 .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-emerald-400.to-teal-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  .from-emerald-400.to-teal-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-emerald-400.to-teal-500 svg,
  .from-emerald-400.to-teal-500 i,
  .from-emerald-400.to-teal-500 .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-gray-400.to-gray-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  .from-gray-400.to-gray-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-gray-400.to-gray-500 svg,
  .from-gray-400.to-gray-500 i,
  .from-gray-400.to-gray-500 .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  [class*="4de5dd"] {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  [class*="4de5dd"]:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  [class*="4de5dd"] svg,
  [class*="4de5dd"] i,
  [class*="4de5dd"] .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-violet-400.to-purple-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: #f0c0cc !important;
    transition: background-image 0.3s ease !important;
  }

  .from-violet-400.to-purple-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-violet-400.to-purple-500 svg,
  .from-violet-400.to-purple-500 i,
  .from-violet-400.to-purple-500 .mari-icon {
    color: #f0c0cc !important;
    fill: none !important;
    stroke: #f0c0cc !important;
  }

  .from-lime-400.via-green-500.to-cyan-500 {
    background-image: linear-gradient(90deg, rgba(40, 18, 24, 0.95), rgba(30, 14, 18, 0.95), rgba(24, 10, 14, 0.95)) !important;
    color: var(--mp-text-primary) !important;
    transition: background-image 0.3s ease !important;
  }

  .from-lime-400.via-green-500.to-cyan-500:hover {
    background-image: linear-gradient(90deg, rgba(30, 14, 18, 0.95), rgba(40, 18, 24, 0.95), rgba(24, 10, 14, 0.95)) !important;
    box-shadow: 0 0 12px rgba(192, 104, 120, 0.35) !important;
  }

  .from-lime-400.via-green-500.to-cyan-500 svg,
  .from-lime-400.via-green-500.to-cyan-500 i,
  .from-lime-400.via-green-500.to-cyan-500 .mari-icon {
    color: var(--mp-text-primary) !important;
    stroke: var(--mp-text-primary) !important;
  }

  [class*="persona"] img,
  [class*="persona"] [class*="avatar"],
  [class*="persona"] [class*="avatar"] img,
  [class*="persona"][class*="avatar"],
  [class*="persona"][class*="icon"],
  [class*="persona"] [class*="icon"],
  [class*="Persona"] img,
  [class*="Persona"] [class*="avatar"],
  [class*="Persona"] [class*="icon"] {
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
  }

  [class*="lorebook"] img,
  [class*="lorebook"][class*="icon"],
  [class*="lorebook"] [class*="icon"],
  [class*="lorebook"][class*="avatar"],
  [class*="lorebook"] [class*="avatar"],
  [class*="lorebook"][class*="thumbnail"],
  [class*="lorebook"] [class*="thumbnail"],
  [class*="Lorebook"] img,
  [class*="Lorebook"][class*="icon"],
  [class*="Lorebook"] [class*="icon"],
  [class*="lorebook-item"] > div:first-child,
  [class*="lorebook-list"] > li > div:first-child,
  [class*="loreBook"] img,
  [class*="loreBook"] [class*="icon"] {
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
  }

  [class*="h-10"][class*="w-10"][class*="overflow-hidden"][class*="bg-[var(--accent)]"][class*="cursor-pointer"][class*="rounded-full"],
  [class*="h-8"][class*="w-8"][class*="shrink-0"][class*="overflow-hidden"][class*="bg-[var(--accent)]"][class*="rounded-full"] {
    border-radius: 9999px !important;
  }

  [class*="h-10"][class*="w-10"][class*="overflow-hidden"][class*="bg-[var(--accent)]"][class*="cursor-pointer"][class*="rounded-full"] img,
  [class*="h-8"][class*="w-8"][class*="shrink-0"][class*="overflow-hidden"][class*="bg-[var(--accent)]"][class*="rounded-full"] img {
