/* ════════ LIGHT MODE ════════ */
[data-theme="light"] {
  color-scheme: light;

  /* core palette light */
  --mp-bg-base: #fff0f3;
  --mp-bg-surface: #fff5f7;
  --mp-bg-elevated: #fde8ed;
  --mp-bg-inset: #f8d8e2;
  --mp-chat-bg: #fff0f3;
  --mp-chat-tint: rgba(255, 240, 243, 0.95);
  --mp-user-tint: rgba(255, 245, 247, 0.98);
  --mp-bot-tint: rgba(253, 232, 237, 0.98);

  --mp-text-primary: #3a0d1a;
  --mp-text-secondary: #8b2040;
  --mp-text-muted: rgba(176, 72, 104, 0.75);
  --mp-text-italics: #a02848;
  --mp-text-quote: #963060;
  --mp-text-underline: #a02848;
  --mp-text-inverted: #fff0f3;

  --mp-pink: #e8829a;
  --mp-pink-soft: rgba(232, 130, 154, 0.3);
  --mp-purple: #a02848;
  --mp-purple-soft: rgba(160, 40, 72, 0.16);
  --mp-blue: #cc6088;
  --mp-blue-soft: rgba(204, 96, 136, 0.16);
  --mp-mint: #e0a8bc;
  --mp-border: rgba(160, 40, 72, 0.45);
  --mp-shadow: rgba(60, 10, 20, 0.10);

  --mp-rainbow: linear-gradient(90deg, #e8829a, #a02848, #cc6088);
  --mp-rainbow-vertical: linear-gradient(180deg, #e8829a, #a02848, #cc6088);

  --background: var(--mp-bg-base);
  --marinara-app-background-paint: var(--mp-bg-base);
  --foreground: var(--mp-text-primary);

  --card: rgba(255, 252, 253, 0.98);
  --card-foreground: var(--mp-text-primary);
  --popover: var(--mp-bg-surface);
  --popover-foreground: var(--mp-text-primary);

  --primary: var(--mp-purple);
  --primary-foreground: var(--mp-text-inverted);

  --secondary: var(--mp-bg-elevated);
  --secondary-foreground: var(--mp-text-primary);

  --muted: var(--mp-bg-inset);
  --muted-foreground: var(--mp-text-muted);

  --accent: var(--mp-purple-soft);
  --accent-foreground: var(--mp-text-primary);

  --destructive: #c82040;
  --destructive-foreground: #fff0f3;

  --border: var(--mp-border);
  --input: var(--mp-border);
  --ring: var(--mp-purple);
  --radius: 1rem;

  --sidebar: var(--mp-bg-elevated);
  --sidebar-foreground: var(--mp-text-primary);
  --sidebar-border: var(--mp-border);
  --sidebar-accent: var(--mp-purple-soft);
  --sidebar-accent-foreground: var(--mp-text-primary);

  --glow-primary: rgba(160, 40, 72, 0.22);
  --glow-accent: rgba(232, 130, 154, 0.28);

  --marinara-app-accent-solid: var(--mp-purple);
  --marinara-app-accent-gradient: linear-gradient(90deg, var(--mp-pink), var(--mp-purple), var(--mp-mint));
  --marinara-chat-chrome-accent: var(--mp-purple);
  --marinara-chat-chrome-accent-gradient: var(--marinara-app-accent-gradient);
  --marinara-chat-chrome-text: var(--mp-text-primary);
  --marinara-chat-chrome-panel-muted: #c07090;

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-xl: 24px;

  body,
  .app-shell,
  #root,
  #main,
  .main-container,
  .app-background,
  .chat-container,
  .chat-background,
  .message-list,
  .chat-messages,
  .chat-view,
  .conversation-pane,
  .mari-chat-shell,
  .mari-chat-background {
    background-color: var(--background) !important;
    color: var(--foreground) !important;
  }

  ::selection {
    background: rgba(160, 40, 72, 0.22) !important;
    color: #3a0d1a !important;
  }

  .glass,
  .glass-strong,
  .card,
  .panel,
  .sidebar,
  .drawer,
  .modal-content,
  .settings-section,
  .chat-list,
  .character-card,
  .persona-card {
